-- ============================================================================
-- Day 5c: quotations (docs/decisions.md D83/D84).
--
-- Everything down to the "HAND-WRITTEN ADDITIONS" marker was generated by
-- `prisma migrate diff --from-schema <previous schema> --to-schema
-- prisma/schema.prisma --script`, UNEDITED. Everything after the marker was
-- added by hand (CHECK constraints — Prisma's schema language cannot express
-- them).
--
-- Additive only: three new tables, one new enum, eleven new NULLABLE columns
-- on organizations (quotation PDF header details, no default values, so
-- staging gets no demo data from this migration).
-- ============================================================================

-- CreateEnum
CREATE TYPE "quotation_status" AS ENUM ('DRAFT', 'SENT', 'ACCEPTED', 'REJECTED', 'EXPIRED');

-- AlterTable
ALTER TABLE "organizations" ADD COLUMN     "address_line1" TEXT,
ADD COLUMN     "address_line2" TEXT,
ADD COLUMN     "city" TEXT,
ADD COLUMN     "country" TEXT,
ADD COLUMN     "email" TEXT,
ADD COLUMN     "gstin" TEXT,
ADD COLUMN     "legal_name" TEXT,
ADD COLUMN     "phone" TEXT,
ADD COLUMN     "postal_code" TEXT,
ADD COLUMN     "state" TEXT,
ADD COLUMN     "website" TEXT;

-- CreateTable
CREATE TABLE "quotations" (
    "id" UUID NOT NULL,
    "organization_id" UUID NOT NULL,
    "number" TEXT NOT NULL,
    "version" INTEGER NOT NULL DEFAULT 1,
    "company_id" UUID NOT NULL,
    "contact_id" UUID NOT NULL,
    "deal_id" UUID,
    "owner_id" UUID,
    "status" "quotation_status" NOT NULL DEFAULT 'DRAFT',
    "issue_date" DATE NOT NULL,
    "valid_until" DATE NOT NULL,
    "currency" TEXT NOT NULL DEFAULT 'INR',
    "discount_percent" DECIMAL(5,2) NOT NULL DEFAULT 0,
    "tax_percent" DECIMAL(5,2) NOT NULL DEFAULT 18,
    "subtotal" DECIMAL(14,2) NOT NULL,
    "discount_amount" DECIMAL(14,2) NOT NULL,
    "tax_amount" DECIMAL(14,2) NOT NULL,
    "total" DECIMAL(14,2) NOT NULL,
    "terms" TEXT,
    "notes" TEXT,
    "sent_at" TIMESTAMPTZ(3),
    "archived_at" TIMESTAMPTZ(3),
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "quotations_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "quotation_line_items" (
    "id" UUID NOT NULL,
    "organization_id" UUID NOT NULL,
    "quotation_id" UUID NOT NULL,
    "position" INTEGER NOT NULL,
    "description" TEXT NOT NULL,
    "quantity" DECIMAL(12,2) NOT NULL,
    "unit_price" DECIMAL(14,2) NOT NULL,
    "discount_percent" DECIMAL(5,2) NOT NULL DEFAULT 0,
    "line_total" DECIMAL(14,2) NOT NULL,
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "quotation_line_items_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "quotation_counters" (
    "organization_id" UUID NOT NULL,
    "year" INTEGER NOT NULL,
    "last_number" INTEGER NOT NULL,
    "updated_at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "quotation_counters_pkey" PRIMARY KEY ("organization_id","year")
);

-- CreateIndex
CREATE INDEX "quotations_organization_id_status_valid_until_idx" ON "quotations"("organization_id", "status", "valid_until");

-- CreateIndex
CREATE INDEX "quotations_organization_id_issue_date_idx" ON "quotations"("organization_id", "issue_date");

-- CreateIndex
CREATE INDEX "quotations_organization_id_company_id_idx" ON "quotations"("organization_id", "company_id");

-- CreateIndex
CREATE INDEX "quotations_organization_id_deal_id_idx" ON "quotations"("organization_id", "deal_id");

-- CreateIndex
CREATE INDEX "quotations_organization_id_owner_id_idx" ON "quotations"("organization_id", "owner_id");

-- CreateIndex
CREATE UNIQUE INDEX "quotations_organization_id_number_key" ON "quotations"("organization_id", "number");

-- CreateIndex
CREATE INDEX "quotation_line_items_organization_id_quotation_id_idx" ON "quotation_line_items"("organization_id", "quotation_id");

-- CreateIndex
CREATE UNIQUE INDEX "quotation_line_items_quotation_id_position_key" ON "quotation_line_items"("quotation_id", "position");

-- AddForeignKey
ALTER TABLE "quotations" ADD CONSTRAINT "quotations_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "quotations" ADD CONSTRAINT "quotations_company_id_fkey" FOREIGN KEY ("company_id") REFERENCES "companies"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "quotations" ADD CONSTRAINT "quotations_contact_id_fkey" FOREIGN KEY ("contact_id") REFERENCES "contacts"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "quotations" ADD CONSTRAINT "quotations_deal_id_fkey" FOREIGN KEY ("deal_id") REFERENCES "deals"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "quotations" ADD CONSTRAINT "quotations_owner_id_fkey" FOREIGN KEY ("owner_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "quotation_line_items" ADD CONSTRAINT "quotation_line_items_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "quotation_line_items" ADD CONSTRAINT "quotation_line_items_quotation_id_fkey" FOREIGN KEY ("quotation_id") REFERENCES "quotations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "quotation_counters" ADD CONSTRAINT "quotation_counters_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;


-- ============================================================================
-- HAND-WRITTEN ADDITIONS
-- ============================================================================

ALTER TABLE "quotations"
  ADD CONSTRAINT "quotations_number_not_blank" CHECK (NULLIF(btrim("number"), '') IS NOT NULL),
  ADD CONSTRAINT "quotations_version_positive" CHECK ("version" >= 1),
  ADD CONSTRAINT "quotations_discount_percent_range" CHECK ("discount_percent" BETWEEN 0 AND 100),
  ADD CONSTRAINT "quotations_tax_percent_range" CHECK ("tax_percent" BETWEEN 0 AND 100),
  ADD CONSTRAINT "quotations_amounts_non_negative" CHECK (
    "subtotal" >= 0 AND "discount_amount" >= 0 AND "tax_amount" >= 0 AND "total" >= 0
  ),
  ADD CONSTRAINT "quotations_valid_until_after_issue" CHECK ("valid_until" >= "issue_date");

ALTER TABLE "quotation_line_items"
  ADD CONSTRAINT "quotation_line_items_description_not_blank" CHECK (NULLIF(btrim("description"), '') IS NOT NULL),
  ADD CONSTRAINT "quotation_line_items_quantity_positive" CHECK ("quantity" > 0),
  ADD CONSTRAINT "quotation_line_items_unit_price_non_negative" CHECK ("unit_price" >= 0),
  ADD CONSTRAINT "quotation_line_items_discount_percent_range" CHECK ("discount_percent" BETWEEN 0 AND 100),
  ADD CONSTRAINT "quotation_line_items_line_total_non_negative" CHECK ("line_total" >= 0),
  ADD CONSTRAINT "quotation_line_items_position_positive" CHECK ("position" >= 1);

ALTER TABLE "quotation_counters"
  ADD CONSTRAINT "quotation_counters_last_number_positive" CHECK ("last_number" >= 1);
